module gray4(input clk, input rst_n, input en, output [3:0] q);
reg [3:0] g; reg p;
always @(posedge clk) begin
 if(!rst_n) begin g<=0; p<=0; end
 else if(en) begin
  p<=~p;
  if(!p) g[0]<=~g[0];
  else if(g[0]) g[1]<=~g[1];
  else if(g[1]) g[2]<=~g[2];
  else g[3]<=~g[3];
 end
end
assign q=g;
endmodule
